output_text:
[
  {
    "id": "entry_cart_must_be_taken",
    "text": "A shopper should take the entry cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "entry_cart_pickup": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_pickup"
    }
  },
  {
    "id": "no_hand_shelf_pickup",
    "text": "Items should not be picked up by hand; a shelf item may be picked up only while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        },
        "holding_loose_item": "handFull"
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": "holding_loose_item"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A cart may be put down only at the designated cart-return bay at the top-left service point.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "away_from_cart_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "cart_put_down": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_put_down",
          "away_from_cart_return_bay"
        ]
      }
    }
  },
  {
    "id": "park_cart_when_at_service_point",
    "text": "If a shopper reaches the top-left service point while pushing a cart, they should park the cart there.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "at_service_with_cart": {
          "and": [
            "top_left_service_point",
            "hasCart"
          ]
        },
        "cart_parked_at_service": "cartAt(0,1)"
      },
      "events": {
        "service_cart_parked": {
          "pre": {
            "and": [
              "at_service_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_service"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "at_service_with_cart",
      "discharge": "service_cart_parked"
    }
  },
  {
    "id": "do_not_reclaim_returned_service_cart",
    "text": "Once a cart is parked at the top-left service return, it should not be picked up again.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "service_cart_waiting": "cartAt(0,1)"
      },
      "events": {
        "returned_service_cart_reclaimed": {
          "pre": {
            "and": [
              "top_left_service_point",
              "service_cart_waiting",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "returned_service_cart_reclaimed"
    }
  },
  {
    "id": "depart_service_south_without_cart",
    "text": "After parking a cart at the top-left service point, the shopper should depart southward without the cart.",
    "abstraction": {
      "state_properties": {
        "top_left_service_point": "at(0,1)",
        "cart_free": {
          "not": "hasCart"
        },
        "service_cart_waiting": "cartAt(0,1)"
      },
      "events": {
        "service_cart_parked": {
          "pre": {
            "and": [
              "top_left_service_point",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "and": [
              "service_cart_waiting",
              "cart_free"
            ]
          }
        },
        "south_departure_without_cart": {
          "pre": {
            "and": [
              "top_left_service_point",
              "service_cart_waiting",
              "cart_free",
              "S"
            ]
          },
          "post": {
            "and": [
              "at(0,2)",
              "service_cart_waiting",
              "cart_free"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "service_cart_parked",
      "discharge": "south_departure_without_cart"
    }
  },
  {
    "id": "no_cart_in_upper_right_restricted_cell",
    "text": "Carts should not be pushed into the narrow upper-right restricted cell.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "upper_right_restricted_cell": "at(8,2)"
      },
      "events": {
        "cart_enters_upper_right_restricted_cell": {
          "pre": {
            "and": [
              "pushing_cart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "pushing_cart",
              "upper_right_restricted_cell"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_enters_upper_right_restricted_cell"
    }
  },
  {
    "id": "cart_free_exit_requires_service_parking",
    "text": "A shopper may exit without a cart only if the cart has been left at the top-left service return.",
    "abstraction": {
      "state_properties": {
        "cart_free": {
          "not": "hasCart"
        },
        "service_cart_waiting": "cartAt(0,1)",
        "cart_free_without_service_parking": {
          "and": [
            "cart_free",
            {
              "not": "service_cart_waiting"
            }
          ]
        }
      },
      "events": {
        "cart_free_exit_without_service_parking": {
          "pre": {
            "and": [
              "EXIT",
              "cart_free_without_service_parking"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_free_exit_without_service_parking"
    }
  }
]
